L30_1 = "{0} 리그"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_DP_GAUNTLET_SEASON_LEAUGE_DESC"
L31_1 = "· 일정 기간마다, 랭크전 시즌이 종료됩니다.\n· 시즌 마감은 마지막 주 일요일 22시입니다.\n· 새 시즌 시작은 월요일 04시 입니다.\n· 지난 시즌 최종 성적에 따라 보상을 지급합니다.\n· 시즌 종료시 정책에 따라 승점이 변동될 수 있습니다.\n· 시즌 결산 이후 승점에 따라 리그가 재배치됩니다."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_DP_GAUNTLET_WEEK_LEAGUE"
L32_1 = "주간 리그"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_DP_GAUNTLET_WEEK_LEAGUE_DESC"
L33_1 = "· 매주 일요일 22시에 주간 랭크전이 마감됩니다.\n· 월요일 04시에 지난 주의 성적에 따라 보상을 지급합니다.\n· 월요일 04시에 주간 리그가 시작됩니다."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_DP_GAUNTLET_INFO_DESC"
L34_1 = "· 장비, 레벨업, 강화로 얻는 능력치는 일부만 적용됩니다.\n· 자신과 비슷한 승점의 유저와 매칭됩니다.\n· 매칭 기준 승점에 작전 능력이 반영됩니다. 작전 능력이 높다면 자신보다 높은 승점의 유저와 매칭될 수 있으며, 작전 능력이 낮다면 자신보다 낮은 승점의 유저와 매칭될 수 있습니다.\n· 자신보다 높은 승점의 유저에게 승리하면 승점을 많이 얻고, 질 경우 적게 잃습니다.\n· 자신보다 낮은 승점의 유저에게 승리하면 승점을 적게 얻고, 질 경우 많이 잃습니다.\n· 자신이 상대보다 승점이 현저히 높지만, 작전 능력이 현저히 낮은 경우, 승점 계산식이 보정됩니다. 이 경우, 기존보다 상대로부터 얻는 승점을 기대할 수 있으며, 지더라도 승점을 덜 잃습니다.\n· 승점을 일정 이상 얻으면 상위 리그로 올라갈 수 있습니다.\n· 일부 리그에서, 해당 리그의 승점보다 100점 이하로 떨어지면 강등될 수 있습니다.\n· 상위 리그에서는 조건을 달성하지 못하면 경고 없이 강등될 수 있습니다.\n· 랭크전에서 고의적인 패배로 점수를 지나치게 떨어뜨린 경우, 매칭 기준 승점이 일정 이하로 하락되지 않게 보정이 적용됩니다."
L32_1[1] = L33_1
L32_1[2] = L34_1
