L38_1 = "SI_DP_GAUNTLET_ASYNC_SEASON_LEAUGE_DESC"
L39_1 = "· 일정 기간마다, 전략전 시즌이 종료됩니다.\n· 시즌 마감은 시즌 종료일 22시입니다.\n· 새 시즌 시작은 시즌 개시일 04시 입니다.\n· 지난 시즌 최종 성적에 따라 보상을 지급합니다.\n· 시즌 종료시 정책에 따라 승점이 변동될 수 있습니다.\n· 시즌 결산 이후 승점에 따라 리그가 재배치됩니다."
