L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_DP_GAUNTLET_ASYNC_WEEK_LEAGUE_DESC"
L40_1 = "· 매주 일요일 밤 10시에 주간 리그가 마감됩니다.\n· 월요일 04시에 지난 주의 성적에 따라 보상을 지급합니다.\n· 월요일 04시에 주간 리그가 시작됩니다."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_DP_GAUNTLET_ASYNC_INFO_LEAGUE_DESC"
L41_1 = "· 장비, 레벨업, 강화로 얻는 능력치는 일부만 적용됩니다.\n· 방어 소대를 반드시 설정해야 전략전에 참여할 수 있습니다.\n· 자신과 비슷한 승점의 유저 3인 중에서, 선택한 유저의 방어 소대와 대전합니다.\n· 전투는 자동으로 진행되며, 유닛은 편성한 순서대로 전투에 배치됩니다.\n· 자신보다 높은 승점의 유저에게 승리하면 승점을 많이 얻고 질 경우 적게 잃습니다.\n· 자신보다 낮은 승점의 유저에게 승리하면 승점을 적게 얻고, 질 경우 많이 잃습니다.\n· 승점을 일정 이상 얻으면 상위 리그로 올라갈 수 있습니다.\n· 일부 리그에서, 해당 리그의 기준 승점 이하로 떨어지면 경고 없이 강등될 수 있습니다."
L39_1[1] = L40_1
L39_1[2] = L41_1
