L49_1 = "밴 단계에 따라, 유닛의 출격 비용이 1씩, 최대 10까지 증가합니다. 또한, 리더 보너스를 받지 못하며 능력치 패널티를 받게 됩니다.\n얼터니움 리액터를 착용한 유닛은 밴 단계에 따라 리액터 해방 단계가 1단계씩 감소합니다."
