L23_1 = "SI_DP_BASE_SUB_MENU_DETAIL_FACTORY"
L24_1 = "우수한 장비는 어설픈 신입 직원도 전투에서 생환할 수 있게 도와줍니다.\n새로운 장비나 보급품 개선이 필요하시면 치프 엔지니어와 상담해 보십시오."
