L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_DP_BASE_SUB_MENU_DETAIL_HANGAR"
L25_1 = "이면세계에 중장비와 인력을 투입하려면 함선은 상시 최상의 상태여야 합니다.\n사장님의 함선을 정비하고 개수하고자 정비과는 오늘도 기꺼이 철야 중입니다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_DP_BASE_SUB_MENU_DETAIL_LAB"
L26_1 = "연구소에서는 생명공학적 시술을 통해 직원들의 잠재력을 계발할 수 있습니다.\n대가도 무척 저렴합니다. 올리비에 박 교수의 시술이 조금 수상쩍기는 하지만요."
