L41_1 = "SI_DP_GAUNTLET_ASYNC_NEW_INFO_LEAGUE_DESC"
L42_1 = "· 상대방이 편성한 방어 소대와 대전합니다.\n· 방어 소대를 편성해야만 전략전에 참여할 수 있습니다.\n· 장비, 레벨업, 강화로 얻는 능력치는 일부만 적용됩니다.\n· 승점을 일정 이상 얻으면 상위 리그로 올라갈 수 있습니다.\n· 전략전 대전에서 일정 횟수 이상 연속으로 승리할 경우, 연승 보너스를 적용합니다.\n· 상위 리그에서는 기준 승점 이하로 떨어지면 경고 없이 강등될 수 있습니다.\n· 방어 실패하면 승점이 감소하며, 일정 횟수부터는 감소하지 않습니다.\n· NPC 대전에서 특정 리그까지 승점을 획득할 수 있습니다.\n· 자신의 방어 소대를 이긴 상대에게 리벤지 대전을 할 수 있습니다."
